def countXorPairs(nums, low, high):
    B = 15
    child = [[-1, -1]]
    cnt = [0]
    total_hi = 0
    total_lo = 0
    X_hi = high + 1
    X_lo = low
    for a in nums:
        for X in (X_hi, X_lo):
            node = 0
            res = 0
            for b in range(B - 1, -1, -1):
                ab = (a >> b) & 1
                if (X >> b) & 1:
                    c = child[node][ab]
                    if c != -1:
                        res += cnt[c]
                    node = child[node][ab ^ 1]
                else:
                    node = child[node][ab]
                if node == -1:
                    break
            if X is X_hi:
                total_hi += res
            else:
                total_lo += res
        node = 0
        for b in range(B - 1, -1, -1):
            ab = (a >> b) & 1
            if child[node][ab] == -1:
                child.append([-1, -1])
                cnt.append(0)
                child[node][ab] = len(child) - 1
            node = child[node][ab]
            cnt[node] += 1
    return total_hi - total_lo
